  "faq.card_schedule_desc": { ko: "다가오는 자격검정 시험 날짜 및 일정을 확인하세요.", en: "Check upcoming certification exam dates and schedules.", ja: "今後の資格検定試験の日程をご確認ください。", zh: "查看即将到来的资格检定考试日期与日程。", hi: "आगामी प्रमाणन परीक्षा की तिथियाँ और कार्यक्रम देखें।", vi: "Xem ngày và lịch các kỳ thi chứng chỉ sắp tới." },
