  "mypage.grading": { ko: "채점 중입니다. 결과는 약 {days}일 후 발표됩니다.", en: "Grading in progress. Results will be announced in about {days} day(s).", ja: "採点中です。結果は約{days}日後に発表されます。", zh: "评分中。结果将在约 {days} 天后公布。", hi: "मूल्यांकन जारी है। परिणाम लगभग {days} दिन बाद घोषित होंगे।", vi: "Đang chấm điểm. Kết quả sẽ công bố sau khoảng {days} ngày." },
  "mypage.expired": { ko: "응시 기간 만료", en: "Exam period expired", ja: "受験期間終了", zh: "应试期间已结束", hi: "परीक्षा अवधि समाप्त", vi: "Hết thời gian dự thi" },
