  "mypage.empty_earned": { ko: "아직 취득한 자격이 없습니다.", en: "You have no certifications yet.", ja: "まだ取得した資格がありません。", zh: "暂无已取得的资格。", hi: "अभी तक कोई प्रमाणन प्राप्त नहीं हुआ।", vi: "Chưa có chứng chỉ nào." },
