  "mypage.tab_ebooks": { ko: "E-BOOK 서재", en: "E-BOOK Library", ja: "E-BOOKライブラリ", zh: "E-BOOK 书架", hi: "E-BOOK लाइब्रेरी", vi: "Thư viện E-BOOK" },
  "mypage.empty_ebooks": { ko: "아직 구매한 이북이 없습니다.", en: "You haven't purchased any eBooks yet.", ja: "まだ購入したeBookがありません。", zh: "尚未购买电子书。", hi: "आपने अभी तक कोई ईबुक नहीं खरीदी है।", vi: "Bạn chưa mua eBook nào." },
  "ebook.store_title": { ko: "이북 스토어", en: "eBook Store", ja: "eBookストア", zh: "电子书商店", hi: "ईबुक स्टोर", vi: "Cửa hàng eBook" },
  "ebook.store_sub": { ko: "구매한 이북은 마이페이지 › 이북 서재에서 읽을 수 있어요.", en: "Purchased eBooks can be read in My Page › eBook Library.", ja: "購入したeBookはマイページ › eBookライブラリで読めます。", zh: "已购买的电子书可在个人中心 › 电子书书架阅读。", hi: "खरीदी गई ईबुक माय पेज › ईबुक लाइब्रेरी में पढ़ी जा सकती हैं।", vi: "eBook đã mua có thể đọc tại Trang cá nhân › Thư viện eBook." },
  "ebook.empty_store": { ko: "등록된 이북이 없습니다.", en: "No eBooks available yet.", ja: "登録されたeBookがありません。", zh: "暂无上架的电子书。", hi: "अभी कोई ईबुक उपलब्ध नहीं है।", vi: "Chưa có eBook nào." },
