  "ebook.bought": { ko: "구매 완료 — 이북 서재에 담겼어요.", en: "Purchased — added to your eBook Library.", ja: "購入完了 — eBookライブラリに追加しました。", zh: "购买完成 — 已加入电子书书架。", hi: "खरीद पूरी — आपकी ईबुक लाइब्रेरी में जोड़ी गई।", vi: "Đã mua — đã thêm vào Thư viện eBook." },
