  "ebook.reader_back": { ko: "이북 서재", en: "Library", ja: "ライブラリ", zh: "书架", hi: "लाइब्रेरी", vi: "Thư viện" },
  "mypage.reissue": { ko: "재발급", en: "Reissue", ja: "再発行", zh: "重新发放", hi: "पुनः जारी करें", vi: "Cấp lại" },
